import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

// This tiny build intentionally handles only this kit's three authored modules.
// It does not fetch packages or depend on a bundler.
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const read = (name) => readFile(path.join(root, name), 'utf8');
const stripModuleSyntax = (source) => source
  .replace(/^import[^\n]+\n/gm, '')
  .replace(/^export \{[^\n]+\};?\n/gm, '')
  .replace(/^export (?=(?:const|let|class|function)\b)/gm, '');

const modules = await Promise.all([
  read('src/art.js'), read('src/state-machine.js'), read('src/lekuvo-mascot.js'),
]);
const bundle = `/* Lekuvo SVG kit — generated by scripts/build.mjs. Edit src/, then rebuild. */\n(() => {\n'use strict';\n${modules.map(stripModuleSyntax).join('\n\n')}\n})();\n`;
await mkdir(path.join(root, 'dist'), { recursive: true });
await writeFile(path.join(root, 'dist/lekuvo-mascot.js'), bundle);

const [page, styles, demo] = await Promise.all([
  read('demo/index.html'), read('demo/demo.css'), read('demo/demo.js'),
]);
const script = `${bundle}\n(async () => {\n${stripModuleSyntax(demo)}\n})().catch(error => {\n  const status = document.getElementById('sequence-status');\n  if (status) status.textContent = 'Preview error: ' + error.message;\n  console.error(error);\n});`;
const preview = page
  .replace('<link rel="stylesheet" href="./demo.css">', `<style>\n${styles}\n</style>`)
  .replace('href="../src/lekuvo-mascot.js"', 'href="./src/lekuvo-mascot.js"')
  .replace('href="../README.md"', 'href="./README.md"')
  .replace('<script type="module" src="./demo.js"></script>',
    `<script>\n${script.replace(/<\/script/gi, '<\\/script')}\n</script>`);
await writeFile(path.join(root, 'preview.html'), preview);
console.log('Built dist/lekuvo-mascot.js and preview.html (no dependencies).');
